package io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.consumer;
import java.util.*; import org.apache.kafka.clients.consumer.ConsumerRecord; import org.apache.kafka.common.TopicPartition; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.kafka.listener.ConsumerSeekAware; import io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.app.TakeoverTracker; import io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.model.TakeoverEvent;
public class TakeoverConsumerB implements ConsumerSeekAware { public static final String ID="scenario-012-consumer-b",LABEL="Consumer B";private final TakeoverTracker tracker;public TakeoverConsumerB(TakeoverTracker tracker){this.tracker=tracker;}@KafkaListener(id=ID,autoStartup="false",topics="${app.kafka.topics.takeover}",groupId="${app.kafka.groups.takeover}")public void onEvent(ConsumerRecord<String,TakeoverEvent> r){tracker.received(r,LABEL);}@Override public void onPartitionsAssigned(Map<TopicPartition,Long> v,ConsumerSeekCallback c){tracker.assigned(LABEL,v.keySet());}@Override public void onPartitionsRevoked(Collection<TopicPartition> v){tracker.revoked(LABEL,v);} }
